    input [2:0] q_in,
    input [2:0] r_in,
    output reg [2:0] Q);
  reg [2:0] q1;
  reg [2:0] q2;
  always @(posedge clk) begin
    if (L) begin
      q1 <= r_in;
      q2 <= q1;
      Q <= q2;
    end else begin
      q1 <= {q1[1] ^ q1[2], q1[0], q1[2]};
      q2 <= {q2[1] ^ q2[2], q2[0], q2[2]};
      Q <= {Q[1] ^ Q[2], Q[0], Q[2]};
    end
  end
endmodule

